procedure PhysioReminderSOP {
  about "Remind patients of upcoming sessions"
  policy PhysioPolicy
  sheet Sessions "Sessions" { patient: Text, mobile: Phone, session_at: DateTime, therapist: Text, status: Text, injury: Text private }
  trigger every day at 08:00

  let all = fetch Sessions
  let due = filter all where date_of(session_at) == today() + 2 days and status == "booked"
  let n = summarize count of due

  if n > 40 {
    notify owner "Cannot send more than 40 reminders per day."
    stop "over limit"
  }

  for each r in due up to 40 {
    let patient = r.patient default "there"
    let session_at = r.session_at
    let message = "Hi {patient}, your session with {therapist} is scheduled for {session_at}."
    let m = draft sms to r.mobile: message
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
    update r set status = "reminded"
  }
}

