procedure CoffeeOrderScheduler {
  about "Order beans based on reorder points"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger every day at 6:30

  let all = fetch Beans
  let needs_order = filter all where bags <= reorder_at
  let orders = group by blend of needs_order
  let valid_orders = filter orders where order_bags * price_per_bag <= $120

  for each blend in valid_orders {
    let order_bags = order_bags of blend
    let total_cost = order_bags * price_per_bag of blend
    let message = "Ordering {order_bags} bags of {blend} from {roaster} at ${total_cost}"
    let ok = request approval of message from owner timeout 2 hours else skip
    send ok
  }

  let remaining = filter needs_order where not in valid_orders
  let n = summarize count of remaining
  if n > 0 {
    notify owner "Found {n} blends needing order, but no valid orders. Please review."
    stop "no valid orders"
  }
}

procedure LoyaltyMemberReminder {
  about "Send 'we miss you' emails to long-ago loyalty members"
  policy CoffeePolicy
  sheet LoyaltyMembers "LoyaltyMembers" { name: Text, email: Email, stamps: Number, last_visit: Date, status: Text }
  trigger every Sunday at 16:00

  let all = fetch LoyaltyMembers
  let long_ago = filter all where days_between(last_visit, today()) >= 30
  let top_15 = sort long_ago by last_visit desc first 15

  for each r in top_15 {
    let name = r.name default "there"
    let message = "Hi {name}, we miss you! We've missed your visits for {days_between(last_visit, today())} days. Come back and join us again!"
    let m = draft email to r.email subject "We Miss You" body message
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}

