procedure HandleSpecialOrders {
  about "Process special orders based on payment"
  policy HardwarePolicy
  sheet SpecialOrders "SpecialOrders" { order_no: Text, customer: Text, phone: Phone, item: Text, ordered_on: Date, arrived: Bool, paid: Money, status: Text }
  trigger when new row r in SpecialOrders

  let total_paid = sum r.paid
  let total_orders = summarize count of r

  if r.status == "waiting" and r.paid >= $amount {
    let count = summarize count of r where r.paid >= $amount
    let msg = "There are {count} special orders still 'waiting' where the customer has paid at least ${$amount}."
    notify owner msg
  }
}

