procedure LaundrySuppliesReorder {
  about "Reorder supplies when below minimum"
  policy LaundryPolicy
  sheet Supplies "Supplies" { item: Text, on_hand: Number, minimum: Number, reorder_qty: Number, supplier: Text, unit_cost: Money }
  trigger every day at 06:00

  let all = fetch Supplies
  let below_min = filter all where on_hand < minimum
  let orders = group below_min by supplier

  for each supplier in orders {
    let items = orders[supplier]
    let total = sum (item.reorder_qty for item in items)
    let total_cost = sum (item.reorder_qty * item.unit_cost for item in items)

