      notify owner "Total reorder cost for {supplier} is {total_cost}, which exceeds $80.00. Please review."
      stop "over order limit"
    }

    let m = draft email to supplier subject "Reorder Request" body "Reordering {total} units of {item} from {supplier} at {unit_cost} each."
    let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
    send ok
  }
}
