procedure ClinicWaitlistUpdate {
  about "Update waitlist when exam is cancelled"
  policy OptomPolicy
  sheet Cancellations "Cancellations" { event_id: Text, slot_text: Text }
  sheet Waitlist "Waitlist" { patient: Text, phone: Phone, joined: Date, status: Text }
  calendar Exams "Exams"

  trigger when new row r in Cancellations

  let c = find Cancellations where event_id == r.event_id else skip
  let e = cancel Cal event r.event_id

  let w = find Waitlist where status == "waiting" and joined <= today()
  let earliest = min(w by joined)

  if is_empty(earliest.patient) {
    let p = "there"
  } else {
    let p = earliest.patient
  }

  if is_empty(earliest.slot_text) {
    let s = "call us for the time"
  } else {
    let s = earliest.slot_text
  }

  let m = draft sms to earliest.phone: "Hi {p}, a spot has opened up in {s}. Please accept it by replying to this message."
  let ok = request approval of m from owner timeout 6 hours else skip
  send ok

  update Waitlist where event_id == r.event_id set status = "offered"
}
```

