  let n = summarize count of reorder

  if n > 4 {
    notify owner "Too many flavors to reorder: {n}. Limit is 4."
    stop "exceeding reorder limit"
  }

  let orders = for each r in reorder up to 4 {
    let order = {
      "flavor": r.flavor,
      "tubs": r.reorder_tubs,
      "supplier": r.supplier,
      "tub_cost": r.tub_cost
    }
