procedure IceRefundProcessing {
  about "Process party cancellations with refund rules"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  let days_until = days_between(r.party_on, today())
  if days_until < 3 {
    notify owner "Party cancellation {r.ref} is less than 3 days away. Please review."
    stop "short notice"
  }

  if r.deposit > $100 {
    notify owner "Refund request {r.ref} is {r.deposit}, over $100. Please review."
    stop "over deposit limit"
  }

  if r.deposit <= $40 {
    let m = draft sms to r.phone: "Hi {r.host default 'there'}, your deposit of ${r.deposit} is being refunded."
    let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
    send ok
    update r set status = "refunded"
    update r set deposit = 0
  } else {
    let m = draft sms to r.phone: "Hi {r.host default 'there'}, your deposit of ${r.deposit} is being refunded. Please approve this message."
    let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
    send ok
    update r set status = "refunded"
    update r set deposit = 0
  }

  let m = draft sms to r.host: "Hi {r.host default 'there'}, your deposit of ${r.deposit} is being refunded. Please approve this message."
  let ok = request approval of m from owner timeout 6 hours else stop "message not approved"
  send ok
}
