  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  trigger every Thursday at 08:30

  let all = fetch Shoots
  let today = today()
  let last_day = today - 1 day
  let delivered = filter all where status == "delivered" and shoot_on >= last_day and shoot_on <= today

  if is_empty(delivered) {
    stop "No delivered clients found"
