procedure PhotostudioFollowUp {
  about "Follow up with delivered clients on Monday"
  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  trigger every monday at 08:30

  let all = fetch Shoots
  let today = today()
  let last3days = today - 3 days
  let delivered = filter all where status == "delivered" and shoot_on >= last3days

  if is_empty(delivered) {
    stop "No delivered clients found"
  }

  let n = summarize count of delivered
  let msg = "Hi {delivered.client default 'there'}, we've received a follow-up request. We'd love to reschedule your shoot. Please let us know your availability."
  let msgs = draft each r in delivered up to 50 sms to r.email: msg

  let ok = request batch approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok

  update delivered set status = "followed-up"
}

