procedure PhotostudioReminder {
  about "Send email reminders for tomorrow's photo shoots"
  policy PhotostudioPolicy
  sheet Shoots "Shoots" { client: Text, email: Email, shoot_on: Date, status: Text, deposit: Money, venue_notes: Text private }
  trigger every day at 18:00

  let all = fetch Shoots
  let tomorrow = today() + 1 day
  let due = filter all where shoot_on == tomorrow and status == "booked"
  let n = summarize count of due

  if n > 20 {
    notify owner "Only 20 reminders can be sent per run."
    stop "max reminders"
  }

  for each r in due up to 20 {
    let m = draft email to r.email subject "Reminder: Your Photo Shoot" body "Hi {r.client}, your photo shoot is tomorrow. Please confirm your attendance."
    let ok = request batch approval of m from owner timeout 15 minutes else stop "batch not approved"
    send ok
  }

  update due set status = "reminded"
}
```

