procedure FloristDeliveryReport {
  about "Send delivery report on Thursdays"
  policy FloristPolicy
  sheet Deliveries "Deliveries" { customer: Text, email: Email, deliver_on: Date, status: Text, price: Money, card_message: Text private }
  trigger every Thursday at 11:00

  let all = fetch Deliveries
  let failed = filter all where status == "failed"
  let n = summarize count of failed
  if n > 0 {
    let msg = "On {date_of(today())}, there were {n} failed deliveries:"
    let msg += "\n\nCustomer | Total Price"
    let table = table of failed by customer, sum(price)
    msg += "\n" + table
    let m = draft email to owner subject "Florist Delivery Report" body msg
    send m
  }
}
