procedure VetPetReminders {
  about "Send reminders to overdue pets"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every Tuesday at 08:00

  let all = fetch Pets
  let overdue = filter all where status == "overdue" and days_between(vaccine_due, today()) <= 3
  let n = summarize count of overdue

  if n == 0 {
    stop "no overdue pets found"
  }

  let msgs = draft each r in overdue up to 200 sms to r.phone: "Hi {r.owner}, we've noticed your vaccine due date is overdue. We'd like to offer a new time. Please let us know when you're available."
  let ok = request batch approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok

  update overdue set status = "contacted"
}

