procedure PlumbingReminderCampaign {
  about "Send reminders to customers who haven't visited in 30 days"
  policy PlumbingPolicy
  sheet Calls "Calls" { customer: Text, phone: Phone, visit_at: DateTime, status: Text, invoice: Money, alarm_code: Text private }
  trigger every day at 09:00

  let all = fetch Calls
  let targets = filter all where days_between(visit_at, today()) >= 30 and status != "cancelled"
  let n = summarize count of targets
  append Calls "Reminder" { customer: customer, phone: phone, visit_at: visit_at, status: status, invoice: invoice, alarm_code: alarm_code }
  let msgs = draft each r in targets up to 20 sms to r.phone: "Hi {r.customer default 'there'}, we've been waiting for you! Come back and visit us soon. We're happy to help with any issues you might have. Don't forget to bring your invoice – we'll need it for the next visit."
  let ok = request batch approval of msgs from owner timeout 2 hours else stop "batch not approved"
  send ok
}

