procedure VetPetReminder {
  about "Send reminders to pet owners who are due for vaccination"
  policy VetPolicy
  sheet Pets "Pets" { owner: Text, phone: Phone, vaccine_due: Date, status: Text, balance: Money, medical_notes: Text private }
  trigger every day at 18:00

  let all = fetch Pets
  let due = filter all where date_of(vaccine_due) == today() - 90 days and status != "inactive"
  let sorted = sort due by date_of(vaccine_due) [desc]

  for each r in sorted up to 10 {
    let m = draft sms to r.phone: "Hi {r.owner}, we've noticed your vaccination due date is approaching. We'd love to invite you back for a check-up. Feel free to reach out if you have any questions!" 
    let ok = request approval of m from owner timeout 2 hours else skip
    send ok
  }
}
```

